import{_ as a,o as r,c as i,aO as e}from"./chunks/framework.BFrk9dwu.js";const l="/travel/lijiang.jpg",o="/travel/lijiang/d1-baisha-1.jpg",n="/travel/lijiang/d1-baisha-2.jpg",d="/travel/lijiang/d1-dayan-1.jpg",s="/travel/lijiang/d1-dayan-2.jpg",g="/travel/lijiang/d2-glacier-1.jpg",h="/travel/lijiang/d2-bluelagoon-1.jpg",q=JSON.parse('{"title":"丽江：雪山脚下的两天","description":"丽江两天的行程：上午白沙古镇、下午大研古城，第二天一整天给玉龙雪山，含住哪、吃什么和几条避坑提醒","frontmatter":{"title":"丽江：雪山脚下的两天","date":"2026-11-17T18:30:00.000Z","description":"丽江两天的行程：上午白沙古镇、下午大研古城，第二天一整天给玉龙雪山，含住哪、吃什么和几条避坑提醒","categories":["life","travel"],"permalink":"/pages/eeb8d2"},"headers":[],"relativePath":"life/travel/lijiang.md","filePath":"life/travel/lijiang.md","lastUpdated":1794900913000}'),c={name:"life/travel/lijiang.md"};function p(f,t,u,_,b,m){return r(),i("div",null,[...t[0]||(t[0]=[e('<h1 id="丽江-雪山脚下的两天" tabindex="-1">丽江：雪山脚下的两天 <a class="header-anchor" href="#丽江-雪山脚下的两天" aria-label="Permalink to &quot;丽江：雪山脚下的两天&quot;">​</a></h1><div class="travel-hero"><img src="'+l+'" alt="玉龙雪山冰川公园 4680 米观景台：游客围着海拔石碑拍照，云层压着雪坡"></div><p>两天也能把丽江走明白：第一天上午去白沙，下午回大研绕巷子；第二天一整天留给玉龙雪山。酒吧街可以不去，清晨的古城值得早起。</p><h2 id="什么时候去" tabindex="-1">什么时候去 <a class="header-anchor" href="#什么时候去" aria-label="Permalink to &quot;什么时候去&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>情况</th></tr></thead><tbody><tr><td>3–5 月、9–11 月</td><td>最舒服，白天二十度上下，雪山也清楚</td></tr><tr><td>6–8 月</td><td>雨季，下午常有阵雨，但人少、房价低</td></tr><tr><td>12–2 月</td><td>雪山最干净，古城早晚冷到零度附近</td></tr><tr><td>国庆、春节</td><td>人多价高，古城里走路都挤，能避开就避开</td></tr></tbody></table><h2 id="怎么到" tabindex="-1">怎么到 <a class="header-anchor" href="#怎么到" aria-label="Permalink to &quot;怎么到&quot;">​</a></h2><ul><li>直飞丽江三义机场，三个半小时左右；机场到古城约 30 公里，机场大巴20元，送了白沙古镇单次车票。</li></ul><p>两天的话，建议<strong>前一晚落地</strong>、直接住大研古城，第一天早上不用赶路。</p><h2 id="两天怎么走" tabindex="-1">两天怎么走 <a class="header-anchor" href="#两天怎么走" aria-label="Permalink to &quot;两天怎么走&quot;">​</a></h2><h3 id="day-1-·-上午白沙-下午大研" tabindex="-1">Day 1 · 上午白沙，下午大研 <a class="header-anchor" href="#day-1-·-上午白沙-下午大研" aria-label="Permalink to &quot;Day 1 · 上午白沙，下午大研&quot;">​</a></h3><p><strong>上午去白沙古镇。</strong> 从古城坐大巴10元。白沙比大研安静得多，看<strong>白沙壁画</strong>、在老院子里坐一上午，天气好能一路望到玉龙雪山。中午在白沙吃，或者回城里吃。</p><div class="travel-grid"><figure><img src="'+o+'" alt="清晨的白沙古镇：石板路两侧是纳西族土墙木屋，尽头是雪山"><figcaption>白沙的早上：石板路一直通到雪山脚下</figcaption></figure><figure><img src="'+n+'" alt="白沙古镇的老院子，三角梅开得正好，石阶上放着藤椅"><figcaption>老院子里的三角梅，坐一上午不嫌久</figcaption></figure></div><p><strong>下午回大研。</strong> 从<strong>四方街</strong>往里走，沿<strong>五一街</strong>、<strong>七一街</strong>慢慢绕，木府外围和狮子山一带能看到连片的屋顶。天快黑时上<strong>万古楼</strong>方向看古城灯火，风大，带件外套。</p><p>晚上避开酒吧街那条主街，往巷子深处找一家小馆子吃饭就行。</p><div class="travel-grid"><figure><img src="'+d+'" alt="俯瞰大研古城连片的灰瓦屋顶，远处是玉龙雪山"><figcaption>狮子山上看过去的屋顶，一层压一层</figcaption></figure><figure><img src="'+s+'" alt="大研古城夜晚的巷子，头顶连串红灯笼，石板路反着光"><figcaption>天黑以后的巷子，灯笼一路挂到尽头</figcaption></figure></div><h3 id="day-2-·-一整天给玉龙雪山" tabindex="-1">Day 2 · 一整天给玉龙雪山 <a class="header-anchor" href="#day-2-·-一整天给玉龙雪山" aria-label="Permalink to &quot;Day 2 · 一整天给玉龙雪山&quot;">​</a></h3><ul><li>包车（淡季20元左右）或跟景区直通车（101公交15元），四十分钟到甘海子。</li><li><strong>大索道</strong>上冰川公园，海拔 4506 米，上去之后走栈道慢一点，别跑别跳。</li><li>下来顺路去<strong>蓝月谷</strong>，水是那种不真实的蓝绿，阴天也不难看。</li><li>下午三四点往回走，回古城补一顿热汤。</li></ul><p>索道票旺季限流，<strong>提前在官方渠道预约</strong>，当天到现场再买大概率没票。</p><div class="travel-grid"><figure><img src="'+g+'" alt="玉龙雪山冰川公园的木栈道，两侧是雪坡，游客在缓慢行走"><figcaption>4506 米的栈道，走两步就得歇一下</figcaption></figure><figure><img src="'+h+'" alt="蓝月谷奶蓝绿色的湖水与层层白色钙化滩，远处是雪山和松林"><figcaption>蓝月谷，阴天也是这个颜色</figcaption></figure></div><h2 id="住哪" tabindex="-1">住哪 <a class="header-anchor" href="#住哪" aria-label="Permalink to &quot;住哪&quot;">​</a></h2><ul><li><strong>大研古城内</strong>：五一街、七一街一带安静，出门就是石板路，两天的行程都从城里出发，住这儿最省事；行李多的话提前联系客栈会骑三奔子过来接。</li><li><strong>不建议</strong>住酒吧街附近，夜里到两三点都在唱。</li></ul><h2 id="吃什么" tabindex="-1">吃什么 <a class="header-anchor" href="#吃什么" aria-label="Permalink to &quot;吃什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>吃的</th><th>说明</th></tr></thead><tbody><tr><td>腊排骨火锅</td><td>象山市场一带最集中，排骨咸香，配土豆和青菜</td></tr><tr><td>鸡豆凉粉</td><td>凉吃酸辣，煎的两面焦更香</td></tr><tr><td>纳西烤鱼</td><td>重香料，下饭</td></tr><tr><td>水性杨花</td><td>海菜花，夏秋才有，清炒或煮汤</td></tr><tr><td>丽江粑粑</td><td>甜的咸的各来一个，当早饭</td></tr></tbody></table><h2 id="避坑" tabindex="-1">避坑 <a class="header-anchor" href="#避坑" aria-label="Permalink to &quot;避坑&quot;">​</a></h2><ul><li><strong>低价包车去拉市海骑马</strong>：路上加价、强制消费的重灾区，想去就自己打车到湖边走走。</li><li><strong>古城里的银器、玉石、虫草</strong>：不懂就别买，标价和实际差得远。</li><li><strong>&quot;免费&quot;拍照、免费编彩辫</strong>：拍完、编完才报价。</li><li><strong>氧气瓶</strong>：古城一二十，山上卖到六七十，提前买好。</li><li><strong>古城维护费</strong>：现在没有。</li></ul><h2 id="花费参考-淡季" tabindex="-1">花费参考 | 淡季 <a class="header-anchor" href="#花费参考-淡季" aria-label="Permalink to &quot;花费参考 | 淡季&quot;">​</a></h2><p>不含大交通，两天三晚人均 210元：住宿 70元 一晚，雪山一天（进山费【100元】 + 索道 + 环保车）240元，吃饭一天七八十。价格年年变，出门前自己再核一遍。</p><p><a href="/life/travel/">← 回旅游攻略</a></p>',28)])])}const j=a(c,[["render",p]]);export{q as __pageData,j as default};
